// AudioContext.js
import React, { createContext, useContext } from 'react';
import selectionSound from './resources/selectionSound.mp3';
import correctSound from './resources/correctSound.mp3';
import incorrectSound from './resources/incorrectSound.mp3';
import buttonSound from './resources/buttonSound.mp3';
import winSound from './resources/winSound.mp3';
// import lifelineSound from './resources/lifelineSound.mp3';

const AudioContext = createContext();

export const useAudio = () => useContext(AudioContext);

export const AudioProvider = ({ children }) => {
    const audioFiles = {
        selectionSound: new Audio(selectionSound),
        correctSound: new Audio(correctSound),
        incorrectSound: new Audio(incorrectSound),
        buttonSound: new Audio(buttonSound),
        winSound: new Audio(winSound),
        // lifelineSound: new Audio(lifelineSound),
    };

    return (
        <AudioContext.Provider value={audioFiles}>
            {children}
        </AudioContext.Provider>
    );
};
