import React, { useEffect } from 'react'
import { useNavigate } from 'react-router-dom';
import './landing.css'
import { useAppState } from '../AppStateContext';
// import Footer from '../components/Footer';
import AnimatedPage from '../AnimatedPage';
import mathiumLogo from '../resources/mathium.svg';
import { useAudio } from '../AudioContext';

const Landing = () => {
    const { isMuted, savedGameState, setIsNewGame, setSavedGameState, setGameMode, setRoomId } = useAppState();
    useEffect(() => {
        const isLocalGamePresent = localStorage.getItem('gameState');
        setSavedGameState(isLocalGamePresent)
        setRoomId('')
        //eslint-disable-next-line
    }, [])
    const { buttonSound } = useAudio();
    const navigate = useNavigate();
    const playButtonSound = () => {
        if (!isMuted) buttonSound.play();
    }
    const handleNewGameButton = () => {
        playButtonSound();
        navigate("/mode");
    }
    const handleRulesButton = () => {
        playButtonSound();
        navigate("/rules");
    }
    const handleLeaderboardButton = () => {
        playButtonSound();
        navigate("/leaderboard");
    }
    const handleContinueButton = () => {
        playButtonSound();
        setIsNewGame(false)
        navigate("/home");
    }
    const handleMultiplayerButton = () => {
        playButtonSound();
        setIsNewGame(true);
        setGameMode('multiplayer')
        navigate("/rooms");
    }

    return (
        <AnimatedPage>
            <div className='page landing'>
                <img className='logo' src={mathiumLogo} alt='Mathium' />
                <div className='menu'>
                    <button className="button-30" onClick={handleNewGameButton}>New Game</button>
                    {savedGameState && <button className="button-30" onClick={handleContinueButton}>Continue</button>}
                    <button className="button-30" onClick={handleMultiplayerButton}>Multiplayer</button>
                    <button className="button-30" onClick={handleRulesButton}>How To Play</button>
                    <button className="button-30" onClick={handleLeaderboardButton}>High Score</button>
                </div>
                {/* <Footer /> */}
                <div className='footer'>Developed With ❤️ By Prakhar Vaish</div>
            </div>
        </AnimatedPage>
    )
}

export default Landing