import React, { useEffect, useState } from 'react';
import "./leaderboard.css";
import AnimatedPage from '../AnimatedPage';
import BackButton from '../components/BackButton';

const Leaderboard = () => {
    const [highScore, setHighScore] = useState(0);
    const [bestTime, setBestTime] = useState('00:00:00');

    useEffect(() => {
        // Retrieve the maximum score for timed mode from localStorage
        const maxScore = localStorage.getItem('highScore');
        if (maxScore) {
            setHighScore(parseInt(maxScore, 10));
        }

        // Retrieve the minimum time for classic mode from localStorage
        const minTime = localStorage.getItem('bestTime');
        if (minTime) {
            const timeInSeconds = parseInt(minTime, 10);
            setBestTime(convertSecondsToTime(timeInSeconds));
        }
    }, []);

    // Function to convert seconds to hh:mm:ss format
    const convertSecondsToTime = (totalSeconds) => {
        const hours = Math.floor(totalSeconds / 3600);
        const minutes = Math.floor((totalSeconds % 3600) / 60);
        const seconds = totalSeconds % 60;

        const padTime = (time) => (time < 10 ? `0${time}` : time);

        return `${padTime(hours)}:${padTime(minutes)}:${padTime(seconds)}`;
    };

    return (
        <AnimatedPage>
            <div className='page'>
                <BackButton></BackButton>
                <h2>High Score</h2>
                <div className='menu'>
                    <div className='score-section'>
                        <h3>Timed Mode</h3>
                        <p>Maximum Score: {highScore}</p>
                    </div>
                    <div className='time-section'>
                        <h3>Classic Mode</h3>
                        <p>Minimum Time: {bestTime}</p>
                    </div>
                </div>
            </div>
        </AnimatedPage>
    );
}

export default Leaderboard;
