import React, { useState } from 'react';
import './rules.css';
import AnimatedPage from '../AnimatedPage';
import BackButton from '../components/BackButton';

const Rules = () => {
    const [isHindi, setIsHindi] = useState(false);

    const toggleLanguage = () => {
        setIsHindi(prevIsHindi => !prevIsHindi);
    };

    return (
        <AnimatedPage>
            <div className='rules page'>
                <BackButton></BackButton>
                <button onClick={toggleLanguage} className='button-30 language-button'>
                    {isHindi ? 'English' : 'हिन्दी'}
                </button>

                <div className={`rules-content ${isHindi ? 'hidden' : ''}`}>
                    <h1>How To Play?</h1>
                    <h2>About the game</h2>
                    <p>Introducing an exciting new math game for you and your kids! This fun and engaging game will boost your arithmetic skills with fast-paced challenges. Sharpen your math abilities while having a great time!</p>
                    <h2>Objective</h2>
                    <p>You will see a number from 1 to 50 at the top of the screen. This number is randomly generated and will appear only once during a game. Your goal is to select 3 numbers from the table using the combination of which, the number can be generated after multiplying and adding or subtracting.</p>
                    <h2>Selection Rules</h2>
                    <ul>
                        <li>The 3 selected numbers must be adjacent and aligned either vertically, horizontally, or diagonally.</li>
                        <li>Use these 3 numbers to generate the target number using exactly one multiplication and one addition or subtraction.</li>
                    </ul>
                    <h2>Mathematical Operation</h2>
                    <ul>
                        <li>Multiply any two of the selected numbers.</li>
                        <li>Add or subtract the third number to/from the result of the multiplication to obtain the target number.</li>
                    </ul>
                    <h2>Game Modes</h2>
                    <ul>
                        <li><strong>Classic Mode:</strong> The random numbers generated are exactly from 1 to 50.</li>
                        <li><strong>Timed Mode:</strong> You have 5 minutes to score as many points as possible by generating the target numbers.</li>
                    </ul>
                    <h2>Stuck?</h2>
                    <ul>
                        <li><strong>Skip:</strong> You can skip a number if it's too difficult.</li>
                        <li><strong>Shuffle:</strong> You can shuffle the entire table's content to get a new set of numbers.</li>
                    </ul>
                    <p>Good luck and have fun with the Math Game!</p>
                </div>

                <div className={`rules-content ${isHindi ? '' : 'hidden'}`}>
                    <h1>इस खेल को कैसे खेलें</h1>
                    <h2>मैथियम खेल के बारे में</h2>
                    <p>पेश है आपके और आपके बच्चों के लिए एक रोमांचक नया गणित का खेल! यह मज़ेदार और आकर्षक गेम तेज़ गति वाली चुनौतियों के साथ आपके अंकगणित कौशल को बढ़ावा देगा। बढ़िया समय बिताते हुए अपनी गणित क्षमताओं को तेज़ करें!</p>
                    <h2>खेल के लाभ:</h2>
                    <ul>
                        <li>यह खेल खिलाड़ियों को गणितीय कौशल, जैसे कि जोड़, घटाव और गुणा का अभ्यास करने में मदद करता है।</li>
                        <li>यह खेल खिलाड़ियों को रणनीतिक रूप से सोचने और समस्याओं को हल करने में मदद करता है।</li>
                        <li>यह खेल खिलाड़ियों को तेज और सटीक होने में मदद करता है।</li>
                    </ul>
                    <h2>खेल खेलने के नियम:</h2>
                    <ul>
                        <li>खेल शुरू करने के लिए, खिलाड़ी को "शुरू" बटन पर क्लिक करना होगा।</li>
                        <li>स्क्रीन के शीर्ष पर, खिलाड़ी को 1 से 50 के बीच की एक बेतरतीब रूप से उत्पन्न संख्या दिखाई देगी। यह संख्या पूरे खेल में केवल एक बार दिखाई देगी।</li>
                        <li>लक्ष्य संख्या प्राप्त करने के लिए, खिलाड़ी को तालिका से तीन संख्याएं चुननी होंगी।</li>
                        <li>चुनी गई तीन संख्याएं एक ही पंक्ति (आड़ा), स्तंभ (खड़ा) या तिरछे में होनी चाहिए।</li>
                        <li>खिलाड़ी को लक्ष्य संख्या प्राप्त करने के लिए चुनी गई तीन संख्याओं का उपयोग करके एक बार गुणा और एक बार जोड़ या घटाव करना होगा।</li>
                    </ul>
                    <h2>खेल के उदाहरण:</h2>
                    <ul>
                        <li>मान लीजिए कि लक्ष्य संख्या 13 है। खिलाड़ी 3, 5 और 2 चुन सकता है। 3 x 5 - 2 = 13</li>
                        <li>मान लीजिए कि लक्ष्य संख्या 29 है। खिलाड़ी 3, 8 और 5 चुन सकता है। 3 x 8 + 5 = 29</li>
                    </ul>
                    <h2>निष्कर्ष:</h2>
                    <p>मैथियम एक मजेदार और शैक्षिक खेल है जो खिलाड़ियों को गणितीय कौशल का अभ्यास करने और अपनी समस्या-समाधान क्षमताओं को विकसित करने में मदद करता है। यह सभी उम्र के खिलाड़ियों के लिए एक बढ़िया खेल है।</p>
                    <h2>खेल के प्रकार :</h2>
                    <ul>
                        <li><strong>क्लासिक मोड:</strong> 1 से 50 तक बेतरतीब ( बिना क्रम के ) संख्याएँ प्रस्तुत होंगी।</li>
                        <li><strong>समयबद्ध मोड:</strong> लक्ष्य संख्याएँ उत्पन्न करके जितना संभव हो उतने अंक प्राप्त करने के लिए आपके पास 5 मिनट हैं।</li>
                    </ul>
                    <h2>लाइफ लाइन्स :</h2>
                    <ul>
                        <li><strong>छोड़ें:</strong> यदि कोई संख्या बहुत कठिन हो तो आप उसे छोड़ सकते हैं।</li>
                        <li><strong>शफ़ल करें:</strong> आप संख्याओं का एक नया सेट प्राप्त करने के लिए संपूर्ण तालिका की सामग्री को शफ़ल कर सकते हैं।</li>
                    </ul>
                    <h2>शुभकामनाएँ और गणित गेम का आनंद लें!</h2>
                </div>
            </div>
        </AnimatedPage>
    );
};

export default Rules;
