import React, { createContext, useContext, useState } from 'react';

const AppStateContext = createContext();

export const useAppState = () => useContext(AppStateContext);

export const AppStateProvider = ({ children }) => {
  const [table, setTable] = useState([]);
  const [showTable, setShowTable] = useState(false);
  const [availableNumbers, setAvailableNumbers] = useState([]);
  const [currentNumber, setCurrentNumber] = useState(null);
  const [score, setScore] = useState(0);
  const [elapsedTime, setElapsedTime] = useState({ hours: 0, minutes: 0, seconds: 0 });
  const [shufflesLeft, setShufflesLeft] = useState(3);
  const [skipsLeft, setSkipsLeft] = useState(3);
  const [gameOver, setGameOver] = useState(false);
  const [gameMode, setGameMode] = useState(null);
  const [isNewGame, setIsNewGame] = useState(false);
  const [isMuted, setIsMuted] = useState(() => localStorage.getItem('isMuted') === 'true');
  const [savedGameState, setSavedGameState] = useState(() => localStorage.getItem('gameState'));
  const [roomId, setRoomId] = useState(null);
  const [playerName, setPlayerName] = useState('');
  const [players, setPlayers] = useState([]);

  return (
    <AppStateContext.Provider value={{
      savedGameState, setSavedGameState,
      gameMode, setGameMode,
      table, setTable,
      showTable, setShowTable,
      availableNumbers, setAvailableNumbers,
      currentNumber, setCurrentNumber,
      score, setScore,
      elapsedTime, setElapsedTime,
      shufflesLeft, setShufflesLeft,
      skipsLeft, setSkipsLeft,
      gameOver, setGameOver,
      isNewGame, setIsNewGame,
      isMuted, setIsMuted,
      roomId, setRoomId,
      playerName, setPlayerName,
      players, setPlayers
    }}>
      {children}
    </AppStateContext.Provider>
  );
};
