import React, { useState, useEffect } from 'react';
import { collection, doc, updateDoc, getDoc, setDoc, onSnapshot } from "firebase/firestore";
import { db } from '../firebase';
import { useNavigate } from 'react-router-dom';
import { useAppState } from '../AppStateContext';
import './rooms.css';
import { useAudio } from '../AudioContext';

const Rooms = () => {
    const navigate = useNavigate();
    const { roomId, setRoomId, setPlayerName, isMuted } = useAppState();
    const [players, setPlayers] = useState([]);
    const [, setRoomStatus] = useState('waiting');
    const [createdRoomId, setCreatedRoomId] = useState('');
    const { buttonSound } = useAudio();
    const playButtonSound = () => {
        if (!isMuted) buttonSound.play();
    }

    const {
        setTable,
        setAvailableNumbers,
        setCurrentNumber,
    } = useAppState();

    let roomNameInput = '';  // Changed to let variable
    let playerNameInput = '';  // Changed to let variable

    useEffect(() => {
        if (roomId) {
            const roomRef = doc(db, "rooms", roomId);
            const unsubscribe = onSnapshot(roomRef, (snapshot) => {
                if (snapshot.exists()) {
                    const roomData = snapshot.data();
                    setPlayers(Object.values(roomData.players || {}));
                    setRoomStatus(roomData.status);
                    if (roomData.status === 'ongoing') {
                        navigate('/multiplayer');
                    }
                } else {
                    console.log("Room does not exist!");
                }
            });

            return () => unsubscribe();
        }
    }, [roomId, navigate]);

    const generateRandomTable = () => {
        const numbers = [];
        const distributionTarget = getRandomDistribution();

        distributionTarget.forEach((count, number) => {
            for (let i = 0; i < count; i++) {
                numbers.push(number + 1);
            }
        });

        shuffleArray(numbers);

        const table = [];
        for (let i = 0; i < 7; i++) {
            const row = [];
            for (let j = 0; j < 7; j++) {
                row.push(numbers[i * 7 + j]);
            }
            table.push(row);
        }
        return table;
    };

    const getRandomDistribution = () => {
        const target = [5, 5, 5, 5, 6, 6, 6, 6, 6];
        shuffleArray(target);
        return target;
    };

    const shuffleArray = (array) => {
        for (let i = array.length - 1; i > 0; i--) {
            const j = Math.floor(Math.random() * (i + 1));
            [array[i], array[j]] = [array[j], array[i]];
        }
        return array;
    };

    const createRoom = async () => {
        playButtonSound();
        if (!roomNameInput || !playerNameInput) {
            alert('Please enter both room name and player name.');
            return;
        }

        try {
            const roomRef = doc(collection(db, "rooms"), roomNameInput);
            await setDoc(roomRef, {
                players: {
                    [playerNameInput]: {
                        name: playerNameInput,
                        score: 0
                    }
                },
                gameState: {},
                status: 'waiting',
                shuffleRequests: 0,
            });
            console.log("Room created with ID: ", roomRef.id);
            setCreatedRoomId(roomRef.id);
            setRoomId(roomNameInput);
            setPlayerName(playerNameInput);

            // Clear input fields
            roomNameInput = '';
            playerNameInput = '';
        } catch (e) {
            console.error("Error adding document: ", e);
        }
    };

    const joinRoom = async () => {
        playButtonSound();
        if (!roomNameInput || !playerNameInput) {
            alert('Please enter both room ID and player name.');
            return;
        }

        const roomRef = doc(db, "rooms", roomNameInput);
        const roomSnap = await getDoc(roomRef);

        if (roomSnap.exists()) {
            const roomData = roomSnap.data();
            if (roomData.status === 'ongoing') {
                alert('The game is already in progress. You cannot join this room.');
                return;
            }

            try {
                await updateDoc(roomRef, {
                    [`players.${playerNameInput}`]: {
                        name: playerNameInput,
                        score: 0
                    }
                });
                console.log(`Player ${playerNameInput} added to room ${roomNameInput}`);
                setRoomId(roomNameInput);
                setPlayerName(playerNameInput);

                // Clear input fields
                roomNameInput = '';
                playerNameInput = '';

            } catch (e) {
                console.error("Error updating document: ", e);
            }
        } else {
            console.log("No such room!");
        }
    };

    const startGame = async () => {
        playButtonSound()
        const roomRef = doc(db, "rooms", roomId);

        const newTable = generateRandomTable();
        const shuffledNumbers = shuffleArray([...Array(50).keys()].map(i => i + 1));
        setTable(newTable);
        setAvailableNumbers(shuffledNumbers.slice(0, -1));
        const nextNumber = shuffledNumbers[shuffledNumbers.length - 1];
        setCurrentNumber(nextNumber);
        setAvailableNumbers(prevNumbers => prevNumbers.slice(0, -1));
        const initialGameState = {
            table: JSON.stringify(newTable),
            availableNumbers: shuffledNumbers.slice(0, -1),
            currentNumber: shuffledNumbers[shuffledNumbers.length - 1],
        };

        try {
            await updateDoc(roomRef, {
                gameState: initialGameState,
                status: 'ongoing'
            });
            console.log('Game state updated successfully');
            navigate('/multiplayer');
        } catch (e) {
            console.error('Error updating game state: ', e);
        }
    };

    return (
        <div className='page'>
            <h1>Create or Join a Room</h1>

            {createdRoomId ? (
                <div>
                    <h2>Current Room</h2>
                    <p>Room ID: {createdRoomId}</p>
                </div>
            ) : (
                <div>
                    <h2>Create Room</h2>
                    <input
                        type="text"
                        placeholder="Room Name"
                        onChange={(e) => roomNameInput = e.target.value} // Use let variable
                    />
                    <input
                        type="text"
                        placeholder="Player Name"
                        onChange={(e) => playerNameInput = e.target.value} // Use let variable
                    />
                    <button className="button-30" onClick={createRoom}>Create Room</button>
                </div>
            )}

            {!createdRoomId && (
                <div>
                    <h2>Join Room</h2>
                    <input
                        type="text"
                        placeholder="Room ID"
                        onChange={(e) => roomNameInput = e.target.value} // Use let variable
                    />
                    <input
                        type="text"
                        placeholder="Player Name"
                        onChange={(e) => playerNameInput = e.target.value} // Use let variable
                    />
                    <button className="button-30" onClick={joinRoom}>Join Room</button>
                </div>
            )}

            {(players.length > 0 || createdRoomId) && (
                <div>
                    <h2>Players in Room</h2>
                    <ul>
                        {players.map((player, index) => (
                            <li key={index}>{player.name}</li>
                        ))}
                    </ul>
                    <button className="button-30" onClick={startGame}>Start Game</button>
                </div>
            )}
        </div>
    );
};

export default Rooms;
