import React, { useState, useEffect, useCallback } from 'react';
import "./home.css";
import Swal from 'sweetalert2'
import { useAppState } from '../AppStateContext';
import { useNavigate } from 'react-router-dom';
import AnimatedPage from '../AnimatedPage';
import hourglass from '../resources/hourglass.png'
import crown from '../resources/crown.png'
import { useAudio } from '../AudioContext';
import BackButton from '../components/BackButton';

const Home = () => {
    const { table,
        setTable,
        showTable,
        setShowTable,
        availableNumbers,
        setAvailableNumbers,
        currentNumber,
        setCurrentNumber,
        score,
        setScore,
        elapsedTime,
        setElapsedTime, shufflesLeft,
        setShufflesLeft,
        skipsLeft,
        setSkipsLeft,
        gameOver,
        setGameOver,
        isNewGame,
        gameMode,
        isMuted,
        setIsMuted,
        setSavedGameState,
        setGameMode,
    } = useAppState();

    const { selectionSound, correctSound, incorrectSound, buttonSound } = useAudio();
    const [selectedCells, setSelectedCells] = useState([]);
    // const [cellColors, setCellColors] = useState({});
    const [flashColors, setFlashColors] = useState({});
    const [lastNumber, setLastNumber] = useState(false);
    const [isPaused, setIsPaused] = useState(false);
    const [incorrectAnswer, setIncorrectAnswer] = useState(false);

    const navigate = useNavigate();

    useEffect(() => {
        const savedLocalGameState = localStorage.getItem('gameState');
        setSavedGameState(savedLocalGameState);
        if (savedLocalGameState) {
            setSavedGameState(savedLocalGameState);
            const { table, availableNumbers, currentNumber, score, elapsedTime, shufflesLeft, skipsLeft, gameMode } = JSON.parse(savedLocalGameState);
            setTable(table);
            setAvailableNumbers(availableNumbers);
            setCurrentNumber(currentNumber);
            setScore(score);
            setElapsedTime(elapsedTime);
            setShufflesLeft(shufflesLeft);
            setSkipsLeft(skipsLeft);
            setShowTable(true);
            setGameMode(gameMode);
        }
        // eslint-disable-next-line
    }, []);


    const selectedSound = () => {
        if (!isMuted) selectionSound.play();
    }
    const playCorrectSound = () => {
        if (!isMuted) correctSound.play();
    }
    const playInorrectSound = () => {
        if (!isMuted) incorrectSound.play();
    }
    // const playLifelineSound = () => {
    //     if (!isMuted) new Audio(lifelineSound).play();    
    // }
    const playButtonSound = () => {
        if (!isMuted) buttonSound.play();
    }


    const generateRandomTable = () => {
        const numbers = [];
        const distributionTarget = getRandomDistribution(); // Randomized target distribution

        // Create an array of numbers based on distributionTarget
        distributionTarget.forEach((count, number) => {
            for (let i = 0; i < count; i++) {
                numbers.push(number + 1); // Adjust for 1-based indexing (1 to 9)
            }
        });

        // Shuffle the numbers array to randomize distribution in the table
        shuffleArray(numbers);

        // Fill the table with randomized numbers
        const table = [];
        for (let i = 0; i < 7; i++) {
            const row = [];
            for (let j = 0; j < 7; j++) {
                row.push(numbers[i * 7 + j]);
            }
            table.push(row);
        }
        return table;
    };

    // const colors = ["red", "blue", "green", "yellow", "purple", "orange", "pink"]; // Example colors
    // const generateRandomColor = () => {
    //     return colors[Math.floor(Math.random() * colors.length)];    
    // };
    // const assignColorsToTable = (table) => {
    //     const assignedColors = {};    

    //     for (let i = 0; i < table.length; i++) {
    //         for (let j = 0; j < table[i].length; j++) {
    //             let color;    
    //             do {
    //                 color = generateRandomColor();    
    //             } while (
    //                 (i > 0 && assignedColors[`${i - 1}-${j}`] === color) ||    
    //                 (j > 0 && assignedColors[`${i}-${j - 1}`] === color)
    //             );

    //             assignedColors[`${i}-${j}`] = color;
    //         }
    //     }

    //     return assignedColors;
    // };

    // Function to generate a random distribution target array
    const getRandomDistribution = () => {
        const target = [5, 5, 5, 5, 6, 6, 6, 6, 6]; // Default target distribution
        shuffleArray(target); // Shuffle the default distribution to make it random
        return target;
    };

    // Function to shuffle an array
    const shuffleArray = (array) => {
        for (let i = array.length - 1; i > 0; i--) {
            const j = Math.floor(Math.random() * (i + 1));
            [array[i], array[j]] = [array[j], array[i]];
        }
        return array;
    };


    // Function to start the timer
    useEffect(() => {
        let timer = null;

        const saveGameState = () => {
            const gameState = {
                table,
                availableNumbers,
                currentNumber,
                score,
                elapsedTime,
                shufflesLeft,
                skipsLeft,
                gameMode,
                isMuted,
            };
            localStorage.setItem('gameState', JSON.stringify(gameState));
        };

        if (!gameOver && !isPaused) {
            timer = setInterval(() => {
                setElapsedTime(prevTime => {
                    let seconds, minutes, hours;
                    if (gameMode === 'timed') {
                        // Decrement timer for timed mode
                        seconds = prevTime.seconds - 1;
                        minutes = prevTime.minutes;
                        hours = prevTime.hours;
                        if (seconds < 0) {
                            seconds = 59;
                            minutes -= 1;
                            if (minutes < 0) {
                                minutes = 59;
                                hours -= 1;
                            }
                        }
                        if (hours <= 0 && minutes <= 0 && seconds <= 0) {
                            setGameOver(true);
                            clearInterval(timer);
                            navigate("/win");
                            return { hours: 0, minutes: 0, seconds: 0 };
                        }
                    } else {
                        // Increment timer for classic mode
                        seconds = prevTime.seconds + 1;
                        minutes = prevTime.minutes + (seconds === 60 ? 1 : 0);
                        hours = prevTime.hours + (minutes === 60 ? 1 : 0);
                        seconds = seconds === 60 ? 0 : seconds;
                        minutes = minutes === 60 ? 0 : minutes;
                    }
                    // Save game state to localStorage
                    if (showTable)
                        saveGameState();

                    return { hours, minutes, seconds };
                });
            }, 1000);
        } else {
            clearInterval(timer);
        }

        return () => clearInterval(timer);
    }, [gameOver, isPaused, setElapsedTime, showTable, navigate, setGameOver, table, availableNumbers, currentNumber, score, elapsedTime, shufflesLeft, skipsLeft, gameMode, isMuted]);


    useEffect(() => {
        if (isNewGame) {
            startNewGame();
        }
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, []);
    const startNewGame = () => {
        const newTable = generateRandomTable();
        const shuffledNumbers = shuffleArray([...Array(50).keys()].map(i => i + 1));
        setTable(newTable);
        // setCellColors(assignColorsToTable(newTable));
        setAvailableNumbers(shuffledNumbers);
        setScore(0);
        if (gameMode === 'timed') {
            setElapsedTime({ hours: 0, minutes: 5, seconds: 0 });
        } else {
            setElapsedTime({ hours: 0, minutes: 0, seconds: 0 });
        }
        setShufflesLeft(3);
        setSkipsLeft(3);
        setGameOver(false);
        setShowTable(true);
        const nextNumber = shuffledNumbers[shuffledNumbers.length - 1];
        setCurrentNumber(nextNumber);
        setAvailableNumbers(prevNumbers => prevNumbers.slice(0, -1));
    };

    const handleNextNumberButtonClick = useCallback((numbers, incrementScore = true) => {
        if (numbers.length === 1) {
            setLastNumber(true);
        }
        const nextNumber = numbers[numbers.length - 1];
        setCurrentNumber(nextNumber);
        setAvailableNumbers(prevNumbers => prevNumbers.slice(0, -1));
        if (incrementScore) {
            setScore(prevScore => prevScore + 1);
        }
    }, [setAvailableNumbers, setCurrentNumber, setScore]);

    const isValidSelection = (prevCells, newCell) => {
        const [newRow, newCol] = newCell.split('-').map(Number);

        if (prevCells.length === 0) {
            return true; // First cell can be selected without restrictions
        }

        if (prevCells.length === 1) {
            const [prevRow, prevCol] = prevCells[0].split('-').map(Number);

            // Check if new cell is adjacent to the first cell
            return Math.abs(prevRow - newRow) <= 1 && Math.abs(prevCol - newCol) <= 1;
        }

        if (prevCells.length === 2) {
            const [prevRow1, prevCol1] = prevCells[0].split('-').map(Number);
            const [prevRow2, prevCol2] = prevCells[1].split('-').map(Number);

            // Check if new cell is adjacent to any of the previous cells horizontally, vertically, or diagonally
            const isAdjacentToPrev1 = Math.abs(prevRow1 - newRow) <= 1 && Math.abs(prevCol1 - newCol) <= 1;
            const isAdjacentToPrev2 = Math.abs(prevRow2 - newRow) <= 1 && Math.abs(prevCol2 - newCol) <= 1;
            const isHorizontal = (prevRow1 === prevRow2 && prevRow1 === newRow);
            const isVertical = (prevCol1 === prevCol2 && prevCol1 === newCol);

            // Check if the new cell forms a diagonal line with the previous cells
            const isDiagonal = Math.abs(prevRow1 - newRow) === Math.abs(prevCol1 - newCol) &&
                Math.abs(prevRow2 - newRow) === Math.abs(prevCol2 - newCol);

            // Check if the new cell is adjacent to any of the previous cells and forms a straight line with them
            // Allow third cell if adjacent to any of the first two cells horizontally, vertically, or diagonally
            return (((isAdjacentToPrev1 || isAdjacentToPrev2) && (isDiagonal || isHorizontal || isVertical)));
        }

        // If already three cells are selected, return false for any new cell
        return false;
    };

    const handleCellClick = (rowIndex, cellIndex) => {
        const cellKey = `${rowIndex}-${cellIndex}`;
        setSelectedCells((prevSelectedCells) => {
            if (prevSelectedCells.length === 3) {
                // Reset selection if trying to select more than 3 cells
                return [];
            } else if (prevSelectedCells.includes(cellKey)) {
                // Deselect cell if it's already selected
                return prevSelectedCells.filter(key => key !== cellKey);
            } else if (prevSelectedCells.length < 3) {
                const newSelectedCells = [...prevSelectedCells, cellKey];
                if (isValidSelection(prevSelectedCells, cellKey)) {
                    selectedSound();
                    return newSelectedCells;
                } else {
                    return [];
                }
            }
            return prevSelectedCells;
        });
    };

    const getSelectedNumbers = () => {
        return selectedCells.map(cell => {
            const [rowIndex, cellIndex] = cell.split('-').map(Number);
            return table[rowIndex][cellIndex];
        });
    };

    const selectedNumbers = getSelectedNumbers();
    const [num1, num2, num3] = selectedNumbers;

    const handleSkipButtonClick = () => {
        if (skipsLeft > 0) {
            // playLifelineSound();
            playButtonSound();
            handleNextNumberButtonClick(availableNumbers, false); // Skip without incrementing score
            if (lastNumber) {
                navigate('/win')
            }
            setSkipsLeft(prevSkips => prevSkips - 1);
        }
    };

    const handleShuffleButtonClick = () => {
        if (shufflesLeft > 0) {
            // playLifelineSound();
            playButtonSound();
            setTable(generateRandomTable());
            setShufflesLeft(prevShuffles => prevShuffles - 1);
        }
    };

    useEffect(() => {
        const result = [
            num1 + num2 * num3,
            Math.abs(num1 - num2 * num3),
            num1 * num2 + num3,
            Math.abs(num1 * num2 - num3),
            num1 * num3 + num2,
            Math.abs(num1 * num3 - num2)
        ];

        if (currentNumber !== null && result.includes(currentNumber)) {
            // Perform actions synchronously to avoid triggering additional renders
            setFlashColors((prevColors) => {
                const newColors = { ...prevColors };
                selectedCells.forEach((cell) => {
                    newColors[cell] = 'correct';
                });
                return newColors;
            });
            playCorrectSound();
            setTimeout(() => {
                setFlashColors({});
                setSelectedCells([]);

                handleNextNumberButtonClick(availableNumbers);
                if (lastNumber) {
                    navigate("/win");
                }
            }, 750);

        } else if (selectedCells.length === 3) {
            setFlashColors((prevColors) => {
                const newColors = { ...prevColors };
                selectedCells.forEach((cell) => {
                    newColors[cell] = 'incorrect';
                });
                return newColors;
            });
            setIncorrectAnswer(true)
            playInorrectSound();
            setTimeout(() => {
                setFlashColors({});
                setSelectedCells([]);
                setIncorrectAnswer(false)
            }, 750);
        }
        // eslint-disable-next-line
    }, [selectedCells]);



    useEffect(() => {
        window.onpopstate = () => {
            playButtonSound();
            navigate("/");
        };
        // eslint-disable-next-line
    }, [navigate, availableNumbers, currentNumber, elapsedTime, gameMode, shufflesLeft, score, skipsLeft, table]);

    const handlePause = () => {
        playButtonSound();
        setIsPaused(true); // Pause the timer
        Swal.fire({
            title: "<strong>Game Paused</strong>",
            icon: "info",
            html: `
              The game is paused. 
              Click "Resume" to continue.
            `,
            showCloseButton: true,
            showCancelButton: true,
            focusConfirm: false,
            confirmButtonText: `Resume`,
            // confirmButtonHtml: ``,
            confirmButtonAriaLabel: "Resume",
            cancelButtonText: `End Game`,
            cancelButtonAriaLabel: "End Game"
        }).then((result) => {
            if (result.isConfirmed || result.dismiss === Swal.DismissReason.esc || result.dismiss === Swal.DismissReason.backdrop || result.dismiss === Swal.DismissReason.close) {
                playButtonSound();
                setIsPaused(false);
                // Resume the timer
            } else if (result.dismiss === Swal.DismissReason.cancel) {
                // Handle end game if needed
                playButtonSound();
                navigate("/");
            }
        });
    };

    const handleMute = () => {
        setIsMuted(prevState => {
            const newState = !prevState;
            localStorage.setItem('isMuted', newState);
            return newState;
        });
    }
    return (
        <AnimatedPage>
            <div className='home page'>
                <BackButton></BackButton>
                {showTable && (
                    <>
                        <p className='number'>{currentNumber}</p>
                        <table className={incorrectAnswer ? 'shake' : ''}>
                            <tbody>
                                {table.map((row, rowIndex) => (
                                    <tr key={rowIndex}>
                                        {row.map((cell, cellIndex) => (
                                            <td key={cellIndex}

                                            >
                                                <div key={cellIndex}
                                                    // className={`cell ${selectedCells.includes(`${rowIndex}-${cellIndex}`) ? 'selected' : ''} ${flashColors[`${rowIndex}-${cellIndex}`] || cellColors[`${rowIndex}-${cellIndex}`]}`}
                                                    className={`cell ${selectedCells.includes(`${rowIndex}-${cellIndex}`) ? 'selected' : ''} ${flashColors[`${rowIndex}-${cellIndex}`]}`}
                                                    onClick={() => handleCellClick(rowIndex, cellIndex)}>{cell}</div>
                                            </td>
                                        ))}
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                        <h2 className="score"><img src={crown} alt='Score:' /> {score}</h2>
                        <h2 className='timer'>
                            <img src={hourglass} alt='Time:' />
                            {String(elapsedTime.hours).padStart(2, '0')}:{String(elapsedTime.minutes).padStart(2, '0')}:{String(elapsedTime.seconds).padStart(2, '0')}
                        </h2>

                        <div className='lifelines'>
                            <div>
                                <button className="button-30" onClick={handleShuffleButtonClick} disabled={shufflesLeft === 0}>
                                    <svg xmlns="http://www.w3.org/2000/svg" width={24} height={24} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={2} strokeLinecap="round" strokeLinejoin="round" className="icon icon-tabler icons-tabler-outline icon-tabler-arrows-shuffle">
                                        <path stroke="none" d="M0 0h24v24H0z" fill="none" />
                                        <path d="M18 4l3 3l-3 3" />
                                        <path d="M18 20l3 -3l-3 -3" />
                                        <path d="M3 7h3a5 5 0 0 1 5 5a5 5 0 0 0 5 5h5" />
                                        <path d="M21 7h-5a4.978 4.978 0 0 0 -3 1m-4 8a4.984 4.984 0 0 1 -3 1h-3" />
                                    </svg>
                                </button>
                                <p>Shuffle</p>
                            </div>
                            <div>
                                <button className="button-30" onClick={handleSkipButtonClick} disabled={skipsLeft === 0}>
                                    <svg xmlns="http://www.w3.org/2000/svg" width={24} height={24} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={2} strokeLinecap="round" strokeLinejoin="round" className="icon icon-tabler icons-tabler-outline icon-tabler-player-skip-forward">
                                        <path stroke="none" d="M0 0h24v24H0z" fill="none" />
                                        <path d="M4 5v14l12 -7z" />
                                        <path d="M20 5l0 14" />
                                    </svg>
                                </button>
                                <p>Skip</p>
                            </div>
                        </div>
                        <button className="button-30 pause-btn" onClick={handlePause} >
                            <svg xmlns="http://www.w3.org/2000/svg" width={24} height={24} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={2} strokeLinecap="round" strokeLinejoin="round" className="icon icon-tabler icons-tabler-outline icon-tabler-player-pause">
                                <path stroke="none" d="M0 0h24v24H0z" fill="none" />
                                <path d="M6 5m0 1a1 1 0 0 1 1 -1h2a1 1 0 0 1 1 1v12a1 1 0 0 1 -1 1h-2a1 1 0 0 1 -1 -1z" />
                                <path d="M14 5m0 1a1 1 0 0 1 1 -1h2a1 1 0 0 1 1 1v12a1 1 0 0 1 -1 1h-2a1 1 0 0 1 -1 -1z" />
                            </svg>
                        </button>

                        <input type="checkbox" id="checkboxInput" checked={isMuted} onChange={handleMute} />
                        <label htmlFor="checkboxInput" className="button-30 mute-btn" >
                            <svg xmlns="http://www.w3.org/2000/svg" width={24} height={24} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={2} strokeLinecap="round" strokeLinejoin="round" className="icon icon-tabler icons-tabler-outline icon-tabler-volume speaker">
                                <path stroke="none" d="M0 0h24v24H0z" fill="none" />
                                <path d="M15 8a5 5 0 0 1 0 8" />
                                <path d="M17.7 5a9 9 0 0 1 0 14" />
                                <path d="M6 15h-2a1 1 0 0 1 -1 -1v-4a1 1 0 0 1 1 -1h2l3.5 -4.5a.8 .8 0 0 1 1.5 .5v14a.8 .8 0 0 1 -1.5 .5l-3.5 -4.5" />
                            </svg>

                            <svg xmlns="http://www.w3.org/2000/svg" width={24} height={24} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={2} strokeLinecap="round" strokeLinejoin="round" className="icon icon-tabler icons-tabler-outline icon-tabler-volume-off mute-speaker">
                                <path stroke="none" d="M0 0h24v24H0z" fill="none" />
                                <path d="M15 8a5 5 0 0 1 1.912 4.934m-1.377 2.602a5 5 0 0 1 -.535 .464" />
                                <path d="M17.7 5a9 9 0 0 1 2.362 11.086m-1.676 2.299a9 9 0 0 1 -.686 .615" />
                                <path d="M9.069 5.054l.431 -.554a.8 .8 0 0 1 1.5 .5v2m0 4v8a.8 .8 0 0 1 -1.5 .5l-3.5 -4.5h-2a1 1 0 0 1 -1 -1v-4a1 1 0 0 1 1 -1h2l1.294 -1.664" />
                                <path d="M3 3l18 18" />
                            </svg>
                        </label>

                    </>
                )}
            </div>
        </AnimatedPage>
    );
};

export default Home;
