import React, { useEffect } from 'react';
import { useAppState } from '../AppStateContext';
import { useNavigate } from 'react-router-dom';
import "./win.css";
import AnimatedPage from '../AnimatedPage';
import { useAudio } from '../AudioContext';
import BackButton from '../components/BackButton';

const Win = () => {
    const { elapsedTime, gameMode, score, isMuted, roomId, players } = useAppState();
    const { buttonSound, winSound } = useAudio();
    const navigate = useNavigate();

    const playButtonSound = () => {
        if (!isMuted) buttonSound.play();
    };

    const playWinSound = () => {
        if (!isMuted && winSound) { // Ensure winSound is not undefined
            winSound.currentTime = 0; // Reset playback position
            winSound.play().catch(err => console.error('Error playing win sound:', err));
        }
    };

    const handleMainMenu = () => {
        playButtonSound();
        navigate("/");
    };

    const handlePlayAgain = () => {
        playButtonSound();
        navigate("/mode");
    };

    useEffect(() => {
        playWinSound();

        if (gameMode !== "multiplayer") {
            const highScore = localStorage.getItem('highScore');
            const bestTime = localStorage.getItem('bestTime');

            if (gameMode === "timed" && (!highScore || score > parseInt(highScore))) {
                localStorage.setItem('highScore', score);
            }

            if (gameMode === "classic" && (!bestTime || (elapsedTime.hours * 3600 + elapsedTime.minutes * 60 + elapsedTime.seconds < JSON.parse(bestTime)))) {
                localStorage.setItem('bestTime', JSON.stringify(elapsedTime.hours * 3600 + elapsedTime.minutes * 60 + elapsedTime.seconds));
            }
            localStorage.removeItem('gameState');
        }
        // eslint-disable-next-line
    }, [gameMode, roomId, score, elapsedTime, isMuted, navigate]);

    return (
        <AnimatedPage>
            <div className='page menu'>
                <BackButton />

                {/* Video background */}
                {/* <video autoPlay muted loop className="background-video">
                    <source src={fireworks} type="video/mp4" />
                    Your browser does not support the video tag.
                </video> */}

                {/* Win message */}
                {gameMode === "classic" &&
                    <h2>
                        Congratulations, you have won the game in {elapsedTime.hours > 0 ? `${elapsedTime.hours} hours ` : ''}{elapsedTime.minutes > 0 ? `${elapsedTime.minutes} minutes ` : ''} {elapsedTime.seconds} seconds
                    </h2>}
                {gameMode === "timed" &&
                    <h2>Congratulations, you have scored {score} points</h2>}
                {gameMode === "multiplayer" && players && (
                    <div className="player-list">
                        <h3>Players</h3>
                        <ul>
                            {Object.entries(players).map(([playerName, playerData]) => (
                                <li key={playerName}>
                                    {playerName} - {playerData.score}
                                </li>
                            ))}
                        </ul>
                    </div>
                )}

                {/* Buttons */}
                <button className="button-30" onClick={handlePlayAgain}>Play Again</button>
                <button className="button-30" onClick={handleMainMenu}>Main Menu</button>
            </div>
        </AnimatedPage>
    );
};

export default Win;
