import React from 'react'
import "./mode.css"
import { useNavigate } from 'react-router-dom'
import { useAppState } from '../AppStateContext'
import AnimatedPage from '../AnimatedPage'
import { useAudio } from '../AudioContext'
import BackButton from '../components/BackButton'

const Mode = () => {
    const { setGameMode, isMuted, setIsNewGame } = useAppState();
    const { buttonSound } = useAudio();
    const navigate = useNavigate();
    const playButtonSound = () => {
        if (!isMuted) buttonSound.play();
    }
    const handleClassicMode = () => {
        setIsNewGame(true);
        playButtonSound();
        localStorage.removeItem('gameState');
        setGameMode("classic");
        navigate('/home');
    }
    const handleTimedMode = () => {
        setIsNewGame(true);
        playButtonSound();
        localStorage.removeItem('gameState');
        setGameMode("timed");
        navigate('/home');
    }
    return (
        <AnimatedPage>
            <div className='page'>
                <BackButton></BackButton>
                <h1>Mode</h1>
                <div className='menu'>
                    <button className="button-30" onClick={handleClassicMode}>Classic</button>
                    <button className="button-30" onClick={handleTimedMode}>Timed</button>
                </div>
            </div>
        </AnimatedPage>
    )
}

export default Mode